import * as stylex from '@stylexjs/stylex';
export const name = stylex.keyframes({
  from: {
    color: 'red',
  },
  to: {
    color: 'blue',
  }
});

import * as stylex from '@stylexjs/stylex';
const COLOR = 'red';
export const name = stylex.keyframes({
  from: {
    color: COLOR,
  },
  to: {
    color: 'blue',
  }
});

import * as stylex from '@stylexjs/stylex';
const COLOR = 'red';
const name = stylex.keyframes({
  from: {
    color: COLOR,
  },
  to: {
    color: 'blue',
  }
});
export const styles = stylex.create({
  root: {
    animationName: `${name}`,
  }
});

import * as stylex from '@stylexjs/stylex';
export const styles = stylex.create({
  root: {
    animationName: stylex.keyframes({
      from: {
        color: 'red',
      },
      to: {
        color: 'blue',
      },
    }),
  },
});

import * as stylex from '@stylexjs/stylex';
export const name = stylex.keyframes({
  from: {
    insetBlockStart: 0,
  },
  to: {
    insetBlockStart: 100,
  }
});
